(window.webpackJsonp=window.webpackJsonp||[]).push([[17],{370:function(t,e){"use strict";e.__esModule=!0,e.default={render:function(){return this.$createElement("div",{staticClass:"theme-default-content content__default lab-wide",domProps:{innerHTML:"\n<div class=\"lab-content join-page\">\r\n<h1 id=\"join-mi2\"><a href=\"#join-mi2\" class=\"header-anchor\">#</a> Join MI² Lab</h1>\r\n<section class=\"join-hero\"><p class=\"eyebrow\">Master’s · Ph.D. · Research Assistant · Internship</p><h2>Research grounded in real medical questions</h2><p>We welcome students and researchers interested in medical imaging, computer vision, and medicine–engineering collaboration. Our work starts from concrete questions and emphasizes method design, careful experiments, and clinical collaboration.</p><div class=\"profile-actions\"><a class=\"button-secondary\" href=\"#application-path\">Application details</a></div></section>\n\r\n<h2 id=\"research-and-training\"><a href=\"#research-and-training\" class=\"header-anchor\">#</a> Research and Training</h2>\n<div class=\"value-grid\"><article><strong>Research practice</strong><p>Work through literature review, method design, experimental analysis, and scientific writing around a well-defined question.</p></article><article><strong>Clinical collaboration</strong><p>Study medical images and clinical data with hospital and research partners, from problem formulation to validation.</p></article><article><strong>Exchange and publication</strong><p>Participate in open discussion, code development, and academic exchange, with support for publishing in medical imaging and AI venues.</p></article></div>\n\r\n<h2 id=\"candidate-profile\"><a href=\"#candidate-profile\" class=\"header-anchor\">#</a> Who We Are Looking For</h2>\r\n<div class=\"candidate-layout\"><ul class=\"check-list\"><li>Applicants for master’s, regular Ph.D., or direct Ph.D. programs at Nanjing University.</li><li>Background in computer science, biomedical engineering, medical imaging, clinical medicine, applied mathematics, or a related discipline.</li><li>Clear interest in medical imaging, computer vision, multimodal large models, medical agents, or medicine–engineering research.</li><li>Strong programming and mathematical foundations; publication or open-source experience is a plus.</li><li>Reliable, collaborative, proactive in communication, and ready for sustained research.</li></ul><aside><p class=\"eyebrow\">Other ways to work with us</p><p>Research assistants, interns, visiting students, and collaborators from hospitals, imaging centers, and life-science research groups are also welcome to get in touch.</p></aside></div>\n\r\n<h2 id=\"admissions\"><a href=\"#admissions\" class=\"header-anchor\">#</a> Admissions</h2>\r\n<div class=\"info-table\"><div><span>Affiliation</span><strong>School of Biomedical Engineering, Nanjing University (Suzhou Campus)</strong></div><div><span>Advisor</span><strong>Prof. Jiong Zhang</strong></div><div><span>Programs</span><strong>Master’s · Regular Ph.D. · Direct Ph.D.</strong></div><div><span>Openings</span><strong>Subject to the annual plans of Nanjing University and the school</strong></div></div>\n\r\n<h2 id=\"application-path\"><a href=\"#application-path\" class=\"header-anchor\">#</a> Application Path</h2>\r\n<div class=\"steps\"><div><span>1</span><h3>Learn about the lab</h3><p>Review recent publications and projects, then identify a medical question or technical direction that interests you.</p></div><div><span>2</span><h3>Prepare materials</h3><p>Prepare a brief introduction, CV, transcript, and research interests. Include links to papers, code, or projects if available.</p></div><div><span>3</span><h3>Send an email</h3><p>Contact <a href=\"mailto:lixiang.cog@smail.nju.edu.cn\">lixiang.cog@smail.nju.edu.cn</a>. Formal applications follow current university and school notices.</p></div></div>\n<div class=\"team-callout application-callout\"><div><p class=\"eyebrow\">Application inquiry</p><h3>Please state your intended program and expected entry year</h3><p>Attach a CV, transcript, and links to representative papers, code, or projects when available.</p></div><a class=\"button-primary\" href=\"mailto:lixiang.cog@smail.nju.edu.cn\">Send email</a></div>\n</div>"}})}}}}]);
